"""Expression semantics: precedence, NULLs, arithmetic, comparisons, functions."""

import unittest

from tests.helpers import MiniSQLTestCase


class TestPrecedence(MiniSQLTestCase):
    def test_mul_before_add(self):
        self.assertValue("1 + 2 * 3", 7)

    def test_parentheses(self):
        self.assertValue("(1 + 2) * 3", 9)

    def test_subtraction_left_to_right(self):
        self.assertValue("10 - 2 - 3", 5)

    def test_division_left_to_right(self):
        self.assertValue("8 / 2 / 2", 2.0)

    def test_mul_div_left_to_right(self):
        self.assertValue("6 / 3 * 2", 4.0)

    def test_concat_at_additive_level_left_to_right(self):
        # (1 + 2) || 3
        self.assertValue("1 + 2 || 3", "33")

    def test_concat_then_add_is_string_arithmetic_error(self):
        # ('a' || 1) + 2 -> arithmetic on a string
        self.assertExprError("'a' || 1 + 2")

    def test_mul_binds_tighter_than_concat(self):
        self.assertValue("'a' || 2 * 3", "a6")

    def test_unary_minus_binds_tighter_than_concat(self):
        # (-1) || 'x'; if unary minus were lower it would negate a string.
        self.assertValue("-1 || 'x'", "-1x")

    def test_unary_minus_binds_tighter_than_mul(self):
        self.assertValue("-2 * 3", -6)
        self.assertValue("2 * -3", -6)

    def test_double_unary_minus(self):
        self.assertValue("- -4", 4)

    def test_unary_minus_on_column(self):
        self.assertRows("SELECT -Price FROM products WHERE ID IN (1, 5)",
                        [(-25,), (3,)])

    def test_comparison_below_additive(self):
        self.assertIs(self.value("1 + 1 = 2"), True)
        self.assertIs(self.value("2 * 3 > 5"), True)

    def test_not_below_comparison(self):
        # NOT (1 = 2), not (NOT 1) = 2
        self.assertIs(self.value("NOT 1 = 2"), True)

    def test_not_below_comparison_in_where(self):
        self.assertRows("SELECT ID FROM products WHERE NOT Qty > 2", [(5,)])

    def test_and_before_or(self):
        self.assertIs(self.value("TRUE OR TRUE AND FALSE"), True)
        self.assertIs(self.value("FALSE AND FALSE OR TRUE"), True)

    def test_not_before_and(self):
        # (NOT FALSE) AND FALSE
        self.assertIs(self.value("NOT FALSE AND FALSE"), False)

    def test_not_before_or(self):
        # (NOT TRUE) OR TRUE
        self.assertIs(self.value("NOT TRUE OR TRUE"), True)

    def test_double_not(self):
        self.assertIs(self.value("NOT NOT TRUE"), True)

    def test_between_operands_are_additive(self):
        self.assertIs(self.value("3 BETWEEN 1 + 1 AND 2 + 2"), True)

    def test_between_followed_by_and(self):
        self.assertRows(
            "SELECT ID FROM products WHERE ID BETWEEN 2 AND 4 AND Qty > 4",
            [(3,), (4,)])

    def test_between_followed_by_or(self):
        self.assertRows(
            "SELECT ID FROM products WHERE ID BETWEEN 2 AND 3 OR ID = 5",
            [(2,), (3,), (5,)])


class TestNull(MiniSQLTestCase):
    def test_arithmetic_with_null(self):
        for expr in ["1 + NULL", "NULL - 1", "2 * NULL", "NULL / 2",
                     "-NULL", "1.5 + NULL"]:
            with self.subTest(expr=expr):
                self.assertNull(expr)

    def test_concat_with_null(self):
        self.assertNull("'a' || NULL")
        self.assertNull("NULL || 'a'")

    def test_comparison_with_null(self):
        for expr in ["NULL = NULL", "1 = NULL", "NULL <> 1", "NULL != 1",
                     "1 < NULL", "NULL >= 1", "'a' > NULL"]:
            with self.subTest(expr=expr):
                self.assertNull(expr)

    def test_not_null(self):
        self.assertNull("NOT NULL")

    def test_like_with_null(self):
        self.assertNull("NULL LIKE 'a'")
        self.assertNull("'a' LIKE NULL")

    def test_scalar_functions_with_null(self):
        for expr in ["LOWER(NULL)", "UPPER(NULL)", "LENGTH(NULL)",
                     "ABS(NULL)", "ROUND(NULL)", "ROUND(NULL, 1)",
                     "ROUND(1.5, NULL)"]:
            with self.subTest(expr=expr):
                self.assertNull(expr)

    def test_three_valued_and(self):
        self.assertIs(self.value("FALSE AND NULL"), False)
        self.assertIs(self.value("NULL AND FALSE"), False)
        self.assertNull("TRUE AND NULL")
        self.assertNull("NULL AND TRUE")
        self.assertNull("NULL AND NULL")

    def test_three_valued_or(self):
        self.assertIs(self.value("TRUE OR NULL"), True)
        self.assertIs(self.value("NULL OR TRUE"), True)
        self.assertNull("FALSE OR NULL")
        self.assertNull("NULL OR FALSE")
        self.assertNull("NULL OR NULL")

    def test_is_null_never_null(self):
        self.assertIs(self.value("NULL IS NULL"), True)
        self.assertIs(self.value("1 IS NULL"), False)
        self.assertIs(self.value("NULL IS NOT NULL"), False)
        self.assertIs(self.value("'' IS NOT NULL"), True)
        self.assertIs(self.value("(1 + NULL) IS NULL"), True)

    def test_is_null_on_column(self):
        self.assertRows(
            "SELECT ID, Qty IS NULL, Qty IS NOT NULL FROM products "
            "WHERE ID <= 2",
            [(1, False, True), (2, True, False)])

    def test_where_keeps_only_true(self):
        # Qty is NULL for ID 2: both the condition and its negation are NULL.
        self.assertRows("SELECT ID FROM products WHERE Qty > 2",
                        [(1,), (3,), (4,)])
        self.assertRows("SELECT ID FROM products WHERE NOT (Qty > 2)",
                        [(5,)])

    def test_where_null_literal_keeps_nothing(self):
        self.assertRows("SELECT ID FROM products WHERE NULL", [])

    def test_where_false_keeps_nothing(self):
        self.assertRows("SELECT ID FROM products WHERE FALSE", [])

    def test_where_is_null(self):
        self.assertRows("SELECT Name FROM products WHERE Category IS NULL",
                        [("doohickey",)])

    def test_where_three_valued_or(self):
        # Qty > 100 is NULL for ID 2, but ID = 2 is TRUE.
        self.assertRows(
            "SELECT ID FROM products WHERE Qty > 100 OR ID = 2", [(2,)])


class TestArithmetic(MiniSQLTestCase):
    def test_int_plus_int_is_int(self):
        self.assertValue("2 + 3", 5)

    def test_int_minus_int_is_int(self):
        self.assertValue("2 - 3", -1)

    def test_int_times_int_is_int(self):
        self.assertValue("4 * 5", 20)

    def test_int_plus_float_is_float(self):
        self.assertValue("2 + 0.5", 2.5)

    def test_float_plus_float_is_float(self):
        self.assertValue("0.5 + 0.5", 1.0)

    def test_int_times_float_is_float(self):
        self.assertValue("2 * 1.5", 3.0)

    def test_float_minus_int_is_float(self):
        self.assertValue("2.5 - 2", 0.5)

    def test_division_is_true_division(self):
        self.assertValue("7 / 2", 3.5)

    def test_exact_division_still_float(self):
        self.assertValue("4 / 2", 2.0)

    def test_negative_division(self):
        self.assertValue("-7 / 2", -3.5)

    def test_division_by_zero_is_null(self):
        self.assertNull("1 / 0")
        self.assertNull("1.5 / 0")
        self.assertNull("1 / 0.0")
        self.assertNull("0 / 0")

    def test_column_arithmetic_types(self):
        self.assertRows(
            'SELECT Qty * 2, "Unit Price" * Qty, Price / 5 FROM products '
            "WHERE ID = 1",
            [(6, 25.5, 5.0)])

    def test_column_division_by_zero_is_null(self):
        self.assertRows("SELECT ID / Qty FROM products WHERE ID = 5",
                        [(None,)])

    def test_arithmetic_on_strings_is_error(self):
        for expr in ["'a' + 1", "1 + 'a'", "'a' - 'b'", "'a' * 2",
                     "'4' / 2", "'1' + '1'"]:
            with self.subTest(expr=expr):
                self.assertExprError(expr)

    def test_arithmetic_on_booleans_is_error(self):
        for expr in ["TRUE + 1", "1 - FALSE", "TRUE * TRUE", "FALSE / 1"]:
            with self.subTest(expr=expr):
                self.assertExprError(expr)

    def test_arithmetic_on_string_column_is_error(self):
        self.assertQueryError("SELECT Name + 1 FROM products")

    def test_concat_string_and_int(self):
        self.assertValue("'a' || 1", "a1")

    def test_concat_strings(self):
        self.assertValue("'foo' || 'bar'", "foobar")

    def test_concat_ints(self):
        self.assertValue("1 || 2", "12")

    def test_concat_float_uses_str(self):
        self.assertValue("'x' || 2.5", "x2.5")
        self.assertValue("'x' || 0.5", "x0.5")

    def test_concat_columns(self):
        self.assertRows(
            "SELECT Name || '-' || ID FROM products WHERE ID <= 2",
            [("widget-1",), ("gadget-2",)])


class TestComparisons(MiniSQLTestCase):
    def test_numeric_comparisons(self):
        cases = {
            "2 < 10": True, "10 < 2": False, "2 <= 2": True, "3 >= 4": False,
            "5 > 4": True, "1 = 1": True, "1 = 2": False, "1 != 2": True,
            "1 <> 1": False, "1 = 1.0": True, "1 < 1.5": True,
            "-1 < 0": True, "2.5 > 2": True,
        }
        for expr, expected in cases.items():
            with self.subTest(expr=expr):
                self.assertIs(self.value(expr), expected)

    def test_string_comparisons_by_code_point(self):
        cases = {
            "'a' < 'b'": True, "'b' < 'a'": False, "'B' < 'a'": True,
            "'abc' < 'abd'": True, "'ab' < 'abc'": True,
            "'10' < '9'": True, "'a' = 'a'": True, "'a' = 'A'": False,
            "'a' <> 'A'": True,
        }
        for expr, expected in cases.items():
            with self.subTest(expr=expr):
                self.assertIs(self.value(expr), expected)

    def test_boolean_equality(self):
        self.assertIs(self.value("TRUE = TRUE"), True)
        self.assertIs(self.value("TRUE = FALSE"), False)
        self.assertIs(self.value("TRUE <> FALSE"), True)
        self.assertIs(self.value("(1 < 2) = TRUE"), True)

    def test_number_vs_string_is_error(self):
        for expr in ["1 < 'a'", "'a' > 1", "1 = 'a'", "'1' = 1",
                     "2.5 >= 'x'", "1 <> 'a'"]:
            with self.subTest(expr=expr):
                self.assertExprError(expr)

    def test_number_column_vs_string_is_error(self):
        self.assertQueryError("SELECT ID FROM products WHERE Price > 'a'")

    def test_where_numeric(self):
        self.assertRows("SELECT Name FROM products WHERE Price > 10",
                        [("widget",), ("gadget",)])

    def test_where_float_column(self):
        self.assertRows('SELECT ID FROM products WHERE "Unit Price" < 1',
                        [(4,), (5,)])

    def test_where_string(self):
        self.assertRows("SELECT ID FROM products WHERE Category = 'tools'",
                        [(1,), (3,)])


class TestIn(MiniSQLTestCase):
    def test_in_true(self):
        self.assertIs(self.value("2 IN (1, 2, 3)"), True)

    def test_in_false(self):
        self.assertIs(self.value("4 IN (1, 2, 3)"), False)

    def test_in_single_item(self):
        self.assertIs(self.value("1 IN (1)"), True)

    def test_in_strings(self):
        self.assertIs(self.value("'b' IN ('a', 'b')"), True)
        self.assertIs(self.value("'B' IN ('a', 'b')"), False)

    def test_in_match_wins_over_null_item(self):
        self.assertIs(self.value("1 IN (NULL, 1)"), True)

    def test_in_no_match_with_null_item_is_null(self):
        self.assertNull("3 IN (1, NULL)")

    def test_in_null_operand_is_null(self):
        self.assertNull("NULL IN (1, 2)")

    def test_in_expression_items(self):
        self.assertIs(self.value("4 IN (1 + 1, 2 * 2)"), True)

    def test_in_int_float_equal(self):
        self.assertIs(self.value("2 IN (1.0, 2.0)"), True)

    def test_not_in_true(self):
        self.assertIs(self.value("4 NOT IN (1, 2, 3)"), True)

    def test_not_in_false(self):
        self.assertIs(self.value("2 NOT IN (1, 2, 3)"), False)

    def test_not_in_with_null_item_is_null(self):
        self.assertNull("3 NOT IN (1, NULL)")

    def test_not_in_match_with_null_item_is_false(self):
        self.assertIs(self.value("1 NOT IN (1, NULL)"), False)

    def test_in_where(self):
        self.assertRows(
            "SELECT ID FROM products WHERE Category IN ('toys', 'x')",
            [(2,), (5,)])

    def test_not_in_where_excludes_nulls(self):
        # Category is NULL for ID 4, so NOT IN is NULL there.
        self.assertRows(
            "SELECT ID FROM products WHERE Category NOT IN ('toys')",
            [(1,), (3,)])


class TestBetween(MiniSQLTestCase):
    def test_between_inside(self):
        self.assertIs(self.value("5 BETWEEN 1 AND 10"), True)

    def test_between_inclusive(self):
        self.assertIs(self.value("1 BETWEEN 1 AND 10"), True)
        self.assertIs(self.value("10 BETWEEN 1 AND 10"), True)

    def test_between_outside(self):
        self.assertIs(self.value("11 BETWEEN 1 AND 10"), False)
        self.assertIs(self.value("0 BETWEEN 1 AND 10"), False)

    def test_between_reversed_bounds_false(self):
        self.assertIs(self.value("5 BETWEEN 10 AND 1"), False)

    def test_between_strings(self):
        self.assertIs(self.value("'b' BETWEEN 'a' AND 'c'"), True)

    def test_between_floats(self):
        self.assertIs(self.value("1.5 BETWEEN 1 AND 2"), True)

    def test_not_between(self):
        self.assertIs(self.value("11 NOT BETWEEN 1 AND 10"), True)
        self.assertIs(self.value("5 NOT BETWEEN 1 AND 10"), False)

    def test_between_null_operand(self):
        self.assertNull("NULL BETWEEN 1 AND 2")

    def test_between_null_low_bound_but_high_fails(self):
        # NULL <= 5 AND 5 <= 1 -> NULL AND FALSE -> FALSE
        self.assertIs(self.value("5 BETWEEN NULL AND 1"), False)

    def test_between_null_high_bound(self):
        # 1 <= 5 AND 5 <= NULL -> TRUE AND NULL -> NULL
        self.assertNull("5 BETWEEN 1 AND NULL")

    def test_not_between_null_low_bound_but_high_fails(self):
        self.assertIs(self.value("5 NOT BETWEEN NULL AND 1"), True)

    def test_between_number_vs_string_is_error(self):
        self.assertExprError("5 BETWEEN 'a' AND 'z'")

    def test_between_where(self):
        self.assertRows("SELECT ID FROM products WHERE Qty BETWEEN 3 AND 5",
                        [(1,), (3,)])

    def test_not_between_where(self):
        self.assertRows(
            "SELECT ID FROM products WHERE Qty NOT BETWEEN 3 AND 5",
            [(4,), (5,)])


class TestLike(MiniSQLTestCase):
    def check(self, cases):
        for expr, expected in cases.items():
            with self.subTest(expr=expr):
                self.assertIs(self.value(expr), expected)

    def test_percent(self):
        self.check({
            "'abc' LIKE 'a%'": True,
            "'abc' LIKE '%c'": True,
            "'abc' LIKE '%b%'": True,
            "'abc' LIKE 'a%c'": True,
            "'ac' LIKE 'a%c'": True,
            "'abc' LIKE '%'": True,
            "'' LIKE '%'": True,
            "'abc' LIKE 'b%'": False,
            "'abc' LIKE '%%'": True,
        })

    def test_underscore(self):
        self.check({
            "'abc' LIKE 'a_c'": True,
            "'abc' LIKE '___'": True,
            "'abc' LIKE '__'": False,
            "'abc' LIKE 'a_'": False,
            "'ac' LIKE 'a_c'": False,
            "'abc' LIKE '_%'": True,
            "'' LIKE '_'": False,
        })

    def test_whole_string_match(self):
        self.check({
            "'abc' LIKE 'b'": False,
            "'abc' LIKE 'ab'": False,
            "'abc' LIKE 'bc'": False,
            "'abc' LIKE 'abc'": True,
            "'abcabc' LIKE 'abc'": False,
        })

    def test_case_sensitive(self):
        self.check({
            "'abc' LIKE 'A%'": False,
            "'ABC' LIKE 'abc'": False,
            "'ABC' LIKE 'A_C'": True,
        })

    def test_regex_metacharacters_are_literal(self):
        self.check({
            "'a.c' LIKE 'a.c'": True,
            "'abc' LIKE 'a.c'": False,
            "'a+b' LIKE 'a+b'": True,
            "'aab' LIKE 'a+b'": False,
            "'a*' LIKE 'a*'": True,
            "'aaa' LIKE 'a*'": False,
            "'(x)' LIKE '(x)'": True,
            "'[ab]' LIKE '[ab]'": True,
            "'a' LIKE '[ab]'": False,
            "'a?' LIKE 'a?'": True,
            "'a' LIKE 'a?'": False,
            "'^a$' LIKE '^a$'": True,
            "'a' LIKE '^a$'": False,
            "'a|b' LIKE 'a|b'": True,
            "'a' LIKE 'a|b'": False,
            "'a\\b' LIKE 'a\\b'": True,
            "'{1}' LIKE '{1}'": True,
            "'x.y.z' LIKE '%.%'": True,
            "'xyz' LIKE '%.%'": False,
        })

    def test_not_like(self):
        self.check({
            "'abc' NOT LIKE 'a%'": False,
            "'abc' NOT LIKE 'x%'": True,
        })

    def test_like_where(self):
        self.assertRows("SELECT ID FROM products WHERE Name LIKE 'w%'",
                        [(1,)])
        self.assertRows("SELECT ID FROM products WHERE Name LIKE '%dg%'",
                        [(2,)])

    def test_not_like_where(self):
        self.assertRows("SELECT ID FROM products WHERE Name NOT LIKE '%g%'",
                        [(1,), (4,), (5,)])

    def test_like_pattern_expression(self):
        self.assertIs(self.value("'abc' LIKE 'a' || '%'"), True)


class TestScalarFunctions(MiniSQLTestCase):
    def test_lower_upper(self):
        self.assertValue("LOWER('AbC')", "abc")
        self.assertValue("UPPER('AbC')", "ABC")

    def test_length(self):
        self.assertValue("LENGTH('abc')", 3)
        self.assertValue("LENGTH('')", 0)

    def test_abs(self):
        self.assertEqual(self.value("ABS(-3)"), 3)
        self.assertEqual(self.value("ABS(3)"), 3)
        self.assertEqual(self.value("ABS(-2.5)"), 2.5)

    def test_round_halves_away_from_zero_to_int(self):
        self.assertValue("ROUND(2.5)", 3)
        self.assertValue("ROUND(-2.5)", -3)
        self.assertValue("ROUND(0.5)", 1)
        self.assertValue("ROUND(-0.5)", -1)
        self.assertValue("ROUND(1.5)", 2)
        self.assertValue("ROUND(3.5)", 4)

    def test_round_non_half(self):
        self.assertValue("ROUND(2.4)", 2)
        self.assertValue("ROUND(2.6)", 3)
        self.assertValue("ROUND(-2.6)", -3)

    def test_round_int_gives_int(self):
        self.assertValue("ROUND(7)", 7)

    def test_round_places_gives_float(self):
        self.assertValue("ROUND(3.14159, 2)", 3.14)
        self.assertValue("ROUND(2, 1)", 2.0)

    def test_round_places_halves_away_from_zero(self):
        # 0.125, 1.25 and 0.375 are exact in binary, so these are true halves.
        self.assertValue("ROUND(0.125, 2)", 0.13)
        self.assertValue("ROUND(-0.125, 2)", -0.13)
        self.assertValue("ROUND(1.25, 1)", 1.3)
        self.assertValue("ROUND(0.375, 2)", 0.38)

    def test_round_zero_places_gives_float(self):
        self.assertValue("ROUND(2.5, 0)", 3.0)

    def test_round_column(self):
        self.assertRows('SELECT ROUND("Unit Price") FROM products '
                        "WHERE ID IN (1, 5)", [(9,), (-2,)])

    def test_coalesce(self):
        self.assertValue("COALESCE(NULL, 2, 3)", 2)
        self.assertValue("COALESCE(1, NULL)", 1)
        self.assertValue("COALESCE(NULL, NULL, 'x')", "x")
        self.assertValue("COALESCE('only')", "only")

    def test_coalesce_all_null(self):
        self.assertNull("COALESCE(NULL, NULL)")

    def test_coalesce_column(self):
        self.assertRows("SELECT COALESCE(Qty, -1) FROM products "
                        "WHERE ID <= 2", [(3,), (-1,)])

    def test_nested_functions(self):
        self.assertValue("UPPER(LOWER('AbC') || 'd')", "ABCD")
        self.assertValue("LENGTH(COALESCE(NULL, 'abcd'))", 4)

    def test_function_on_column(self):
        self.assertRows("SELECT UPPER(Name), LENGTH(Name) FROM products "
                        "WHERE ID = 4", [("DOOHICKEY", 9)])

    def test_unknown_function_is_error(self):
        self.assertExprError("FOO(1)")
        self.assertExprError("SQRT(4)")

    def test_unknown_function_on_empty_table_is_error(self):
        # Interpretation: unknown functions are rejected even with no rows.
        self.assertQueryError("SELECT FOO(x) FROM empty")

    def test_wrong_arity_is_error(self):
        for expr in ["LOWER()", "LOWER('a', 'b')", "UPPER()",
                     "LENGTH('a', 'b')", "ABS()", "ABS(1, 2)", "ROUND()",
                     "ROUND(1, 2, 3)"]:
            with self.subTest(expr=expr):
                self.assertExprError(expr)


